      case 'preview':{
        need(plain(args.input)&&Object.keys(args.input).every(key=>PORTFOLIO_PREVIEW_FIELDS.includes(key)),'PORTFOLIO_INVALID_REQUEST','Supply the original complete calendar selection.');
