const fault = (code, message) => Object.assign(new Error(message), { code });
const codeOf = error => /^(?:ACCOUNTING_|QBO_|OAUTH_)[A-Z0-9_]{1,100}$/.test(error?.code ?? '')
  ? error.code : 'ACCOUNTING_QBO_OAUTH_UNAVAILABLE';
